func convertUsersToDataTableRows(users []UserTableRow) []DataTableRow {
	rows := make([]DataTableRow, len(users))
	for i, user := range users {
		rows[i] = DataTableRow{
			ID: user.ID.String(),
			Data: map[string]any{
				"name":        user.Name,
				"email":       user.Email,
				"role":        user.Role,
				"status":      user.Status,
				"tenant_name": "Tenant Name", // This would be fetched from tenant relation
				"last_login":  user.LastLogin,
			},
			Actions: []DataTableAction{
				{
					Text:    "View",
					Icon:    "fas fa-eye",
					Variant: "primary",
					Href:    "/console/users/" + user.ID.String(),
				},
				{
					Text:    "Edit",
					Icon:    "fas fa-edit",
					Variant: "secondary",
					Href:    "/console/users/" + user.ID.String() + "/edit",
				},
			},
		}
	}
	return rows
}

